solutions.naive:
class Solution:
    def repeatedSubstringPattern(self, s: str) -> bool:
        n = len(s)
        for length in range(1, n):
            if n % length == 0:
                part = s[:length]
                if part * (n // length) == s:
                    return True
        return False

